const output = [];
for (const inputItem of $input.all()) {
  const source = inputItem.json || {};
  const evidence = Array.isArray(source.evidence) ? source.evidence : [];
  const valid = evidence.filter((item) => item && item.evidence_id && item.resumen).slice(0, 50);
  if (source.eligible !== true || Number(source.evidence_count || 0) < 3 || valid.length < 3) continue;
  output.push({ json: { ...source, evidence: valid, evidence_json: JSON.stringify(valid), model_version: 'gpt-5.4-mini', prompt_version: 'learning-patterns-v7' } });
}
return output;

const responses = $input.all();
const sourceItems = $('02 F7 Exigir evidencia suficiente').all();
const output = [];
const collect = (v) => typeof v === 'string' ? v : Array.isArray(v) ? v.map(collect).filter(Boolean).join('\n') : v && typeof v === 'object' ? collect(v.text || v.output_text || v.content || v.message || v.output || v.response || '') : '';
const text = (v, max) => String(v || '').trim().slice(0, max);
const allowedCategories = new Set(['decision','objetivo','ejecucion','contexto','general']);
const allowedTrends = new Set(['positiva','neutral','negativa','mixta']);
const allowedTypes = new Set(['decision_result','goal_event','action_event']);
const allowedSignals = new Set(['positivo','neutral','negativo','inconcluso']);
for (let responseIndex = 0; responseIndex < responses.length; responseIndex++) {
  const responseItem = responses[responseIndex];
  const paired = Array.isArray(responseItem.pairedItem) ? responseItem.pairedItem[0] : responseItem.pairedItem;
  const sourceIndex = Number.isInteger(paired?.item) ? paired.item : responseIndex;
  const source = sourceItems[sourceIndex]?.json || sourceItems[responseIndex]?.json || {};
  const raw = collect(responseItem.json).replace(/^\`\`\`(?:json)?\s*/i, '').replace(/\s*\`\`\`$/i, '').trim();
  const start = raw.indexOf('{'); const end = raw.lastIndexOf('}');
  if (start < 0 || end <= start) continue;
  let parsed; try { parsed = JSON.parse(raw.slice(start, end + 1)); } catch { continue; }
  const available = new Map((Array.isArray(source.evidence) ? source.evidence : []).map((item) => [String(item.evidence_id), item]));
  const learnings = (Array.isArray(parsed.learnings) ? parsed.learnings : []).slice(0, 3).map((item) => {
    const seen = new Set();
    const evidence = (Array.isArray(item?.evidence) ? item.evidence : []).map((ref) => {
      const id = String(ref?.evidence_id || ''); const original = available.get(id);
      if (!original || seen.has(id) || !allowedTypes.has(String(original.evidence_type))) return null;
      seen.add(id);
      return { evidence_type: original.evidence_type, evidence_id: id, signal: allowedSignals.has(String(original.signal)) ? original.signal : 'neutral', resumen: text(original.resumen, 2000), ocurrido_at: original.ocurrido_at };
    }).filter(Boolean);
    if (evidence.length < 2) return null;
    const confidenceCap = evidence.length >= 5 ? 0.90 : evidence.length >= 3 ? 0.80 : 0.70;
    const confidence = Math.max(0, Math.min(confidenceCap, Number(item?.confianza || 0.5)));
    const positive = evidence.filter((e) => e.signal === 'positivo').length;
    const negative = evidence.filter((e) => e.signal === 'negativo').length;
    const times = evidence.map((e) => new Date(e.ocurrido_at).getTime()).filter(Number.isFinite);
    const key = text(item?.clave, 160).toLowerCase().replace(/[^a-z0-9_-]+/g, '-').replace(/^-+|-+$/g, '');
    const pattern = text(item?.patron, 500); const recommendation = text(item?.recomendacion, 500);
    if (!key || !pattern || !recommendation) return null;
    return { clave: key, categoria: allowedCategories.has(String(item?.categoria)) ? item.categoria : 'general', patron: pattern, recomendacion: recommendation, tendencia: allowedTrends.has(String(item?.tendencia)) ? item.tendencia : 'mixta', confianza: confidence, evidence_count: evidence.length, positive_count: positive, negative_count: negative, first_observed_at: times.length ? new Date(Math.min(...times)).toISOString() : null, last_observed_at: times.length ? new Date(Math.max(...times)).toISOString() : null, evidence, metadata: { total_available_evidence: Number(source.evidence_count || 0) } };
  }).filter(Boolean);
  if (!learnings.length) continue;
  output.push({ json: { usuario_id: source.usuario_id, analysis_date: source.analysis_date, evidence_count: Number(source.evidence_count || (Array.isArray(source.evidence) ? source.evidence.length : 0)), payload: { learnings }, model_version: source.model_version, prompt_version: source.prompt_version, execution_id: String($execution.id || '') } });
}
return output;
